/*
 * Arabic copy for the eight Arabic-market country pages.
 *
 * This lives in its own module because Astro hoists getStaticPaths out of the
 * component scope: a const declared in the page frontmatter is invisible to it,
 * but an import is not.
 *
 * Every regulatory fact here renders a claim that already exists in
 * src/data/country-detail.ts. Nothing new is asserted.
 */

export interface ArProviderText {
  note: string;
}
export interface ArCountry {
  name: string;        /* formal name, used in headings and schema */
  shortName: string;   /* the form that reads naturally mid-sentence */
  lede: string;
  metaDescription: string;
  einvoicing?: {
    scheme: string;
    authority: string;
    status: string;
    appliesTo: string;
    requirementsAr: Record<string, string>;
  };
  taxAr: Record<string, string>;
  payrollAr: Record<string, string>;
  accountingAr: Record<string, string>;
  paymentsAr: Record<string, ArProviderText>;
  shippingAr: Record<string, ArProviderText>;
  nativeAr: Record<string, string>;
  customAr: Record<string, string>;
}

